from pathlib import Path
p=Path('agent_notes/lbc_other_attributes.md')
text=p.read_text(encoding='utf-8')
repls=[
('Пограничные варианты сохраняют собственный шаг и scale: `max_health` обычный `+2`, `max_health_1` — `+1`, `_down_two` — `−2`, `_down_eight` — `−8`, `_up_eight` — `+8`; knockback resistance обычный шаг равен 10, тогда как `_down`/`_up` тоже меняют на 10. Для `movement_speed` базовый шаг ±2000 при scale 100000 (±0.02), tiny +100 (0.001). `_godclaw`-версии не являются фиксированным бонусом: они складывают `tmp1` (или вычитают его у отдельных атрибутов) после чтения базы с указанным scale.', 'Пограничные варианты сохраняют собственный шаг и scale: `max_health` обычный `+2`, `max_health_1` — `+1`, `_down_two` — `−2`, `_down_eight` — `−8`, `_up_eight` — `+8`; knockback resistance обычный шаг равен 10, и `_down`/`_up` тоже меняют на 10. Для `movement_speed` обычный шаг ±2000 при scale 100000 (±0.02), tiny +100 (0.001). Рандомные `random_damage`, `random_health`, `random_speed` заменяют базу случайным значением от 0.001 до соответственно 3×, 2.5× и 4× прежнего значения, шаг 0.001; после замены дают nausea 3 seconds и blindness 2 seconds, затем отзывают свой advancement. `reduce_hp_armor` выполняет три вычитания по 2: max health и armor обновляются ожидаемыми функциями, но третья ветка читает `armor_toughness` и ошибочно вызывает `armor_update`, поэтому она перезаписывает armor значением toughness−2, а toughness не обновляет. `gen.py` — неисполняемый генератор, перечисляющий 26 godclaw-файлов и шаблон с get-scale 1000, `tmp1` и коэффициентом 0.001; существующие файлы содержат разные scale и коэффициенты, поэтому фактическая таблица взята из самих функций.'),
('Успешное употребление расходует предмет по самому consume trigger, затем reward вызывает функцию ниже. Обработчик обычно применяет эффект либо вызывает attribute handler, показывает subtitle и звук `minecraft:lbcsounds.pill_good`/`pill_bad`, после чего отзывает advancement `lbc:pills/pill_*` для следующего предмета. Отзыв advancement не возвращает таблетку.', 'Успешное употребление расходует предмет по самому consume trigger, затем reward вызывает функцию ниже. Loot table `lbc:kit/pill` выдаёт одну `minecraft:cookie` с consume time 0.2 s, `minecraft:food` nutrition/saturation 1 и can_always_eat=true; для hash N ставит model `lbc:pills/pill_N` и custom data `{pill:N}`. Таким образом, pill:N из advancement связывает предмет комплекта с обработчиком. Обработчик применяет эффект либо вызывает attribute handler, показывает subtitle и звук `minecraft:lbcsounds.pill_good`/`pill_bad`, после чего отзывает advancement `lbc:pills/pill_*` для следующего предмета. Отзыв advancement не возвращает таблетку.'),
('## Случайный выбор изменения атрибута\n\n', '## Случайный выбор изменения атрибута\n\n`random_attrs_up` draws uniform #rand 1..26 and calls exactly one of 26 listed handlers; options 8 and 11 are decreases to burning_time and fall_damage_multiplier despite the name “up”. `random_attrs_down` rolls the `lbc:chance50` predicate independently for each of eight handlers, so one activation may apply any subset, including none or several. `gen_rand` draws an integer 1..tmp; `randdouble_ab` draws 0..tmpi. These helpers only draw/store the value; the caller decides what it represents.\n\n'),
('## Передача предметов из инвентаря в item entities\n\n', '## Передача предметов из инвентаря в item entities\n\nОбычный caller `lbc:projectiles/gadgets/honey_pl` проверяет каждый присутствующий слот 0..35 и вызывает соответствующий helper; затем отдельно проверяет offhand и четыре armor slots. Поэтому функция с конкретным slot не выбирает его сама: ветку выбирает caller по факту наличия предмета.\n\n'),
('## Новый игровой цикл: legacy предметы и очистка мира\n\n', '## Новый игровой цикл: legacy предметы и очистка мира\n\n`click` отключает три gamerule выпадения, стирает и убивает non-player entities кроме `supernovacore`, чистит игроков и эффекты, сбрасывает расписания `everythingend/*` и `baffledend/*`, reset state/score, возвращает gamerules, очищает карту и строит четыре legacy шаблона; затем ставит legacy-флаг, запускает циклы, выдаёт краткие защитные эффекты и grants `new_world`. `legacy_tick`, `legacy_tick_1s`, `legacy_tick_5s`, `legacy_tick_5t` самопланируются с указанным периодом и обрабатывают игроков не в spectator; player-функции проверяют старые repeating-command-block custom_data либо экипировку, обновляют эффекты и cooldown scores. `magic_boost_belt`/`hat` уменьшают четыре cooldown-счётчика на 2/4 за вызов. `click` вызывается из `spell1_default` при SelectedItem `item_balance:1` и запускает новый игровой цикл.\n\n')]
for a,b in repls:
 if a not in text: print('missing marker',a[:40])
 text=text.replace(a,b)
note='`attribute base get S` сохраняет в scoreboard целое квантованное значение, поэтому таблица `delta/S` показывает шаг после квантования, а не гарантирует абсолютную дельту от любой дробной исходной базы.'
if note not in text:
 text=text.replace('tiny +100 (0.001). Рандомные', 'tiny +100 (0.001). '+note+' Рандомные')
lines=text.splitlines()
for i,line in enumerate(lines):
 if line.startswith('| `random_damage` |'):
  lines[i]='| `random_damage` | `attack_damage` | 3000 | random 1..(current×3000) | 0.001..(current×3), step 0.001 | `attack_damage_update` | `lbc:eat_damage_penis` |'
 elif line.startswith('| `random_health` |'):
  lines[i]='| `random_health` | `max_health` | 2500 | random 1..(current×2500) | 0.001..(current×2.5), step 0.001 | `max_health_update` | `lbc:eat_healthy_penis` |'
 elif line.startswith('| `random_speed` |'):
  lines[i]='| `random_speed` | `movement_speed` | 4000 | random 1..(current×4000) | 0.001..(current×4), step 0.001 | `movement_speed_update` | `lbc:eat_fast_penis` |'
 elif line.startswith('| `reduce_hp_armor` |'):
  lines[i]='| `reduce_hp_armor` | `max_health`, `armor`, `armor_toughness` | 1 | `−2` each | health −2; armor −2; toughness branch routes to `armor_update` | `mixed` | `—` |'
p.write_text('\n'.join(lines)+'\n',encoding='utf-8')
